#!/usr/bin/env bash
# recipes/crate-pin-project-internal--1-1-4/build.sh -- stage the pin-project-internal 1.1.4 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/pin-project-internal-1.1.4"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
# cargo reads a directory-source entry's checksums from here. "package" is the
# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"266c042b60c9c76b8d53061e52b2e0d1116abc57cefc8c5cd671619a56ac3690"}\n' > "${dest}/.cargo-checksum.json"
